/* pointers and lengths for each waveform */
static const uint16_t * const waveforms[NUM_WAVES] = {
    Sin_LUT, Triangle_LUT, Saw_LUT, Piano_LUT, Guitar_LUT, Drum_LUT
};

/* corresponding lengths (samples per cycle) */
static const uint32_t wave_lens[NUM_WAVES] = {
    NS1, NS1, NS1, NS2, NS2, NS2
};

static const char * const wave_names[NUM_WAVES] = {
    "Sine", "Triangle", "Saw", "Piano", "Guitar", "Drum"
};

/* current waveform index */
static volatile uint32_t current_wave = 0;

/* ticks between DMA transfers (updated whenever waveform changes) */
static volatile uint32_t TIM2_Ticks = 0u;

/* destination address for DMA */
static const uint32_t DestAddress = (uint32_t)&(TIM3->CCR3);

/* debounce */
static volatile uint32_t last_press_ms = 0u;

